using Demo.Orders;
class OrderReader {
    static Order Sample() => new Order { OrderId = "O-1", AmountCents = 1250, Currency = "USD" };
    static object Observe(Order order) => new { amount_cents = order.AmountCents, currency = order.Currency };
    static bool IsUsd(Order order) => order.Currency == "USD";
}

from generated.orders_pb2 import Order

def sample():
    return Order(order_id="O-1", amount_cents=1250, currency="USD")
def observe(order):
    return {"amount_cents": order.amount_cents, "currency": order.currency}
def is_usd(order):
